const slug = text => text.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/(^-|-$)/g,'');
const key = (section,label,suffix='') => `${section.id}-${slug(label)}${suffix}`;
function otherInput(section,label) { const id=key(section,label,'-other'); return `<input class="other-input" data-key="${id}" data-label="${label}" value="${state[id]||''}" placeholder="Describe finding">`; }
function chips(section,label,options,type='choice') { const id=key(section,label), multi=type==='multiChoice', selected=multi?(Array.isArray(state[id])?state[id]:[]):[]; return `<div class="choices">${options.map(option=>`<label class="choice-chip"><input type="${multi?'checkbox':'radio'}" ${multi?`data-multi-key="${id}"`:`name="${id}"`} value="${option}" data-label="${label}" ${multi?selected.includes(option)?'checked':'':state[id]===option?'checked':''}><span>${option}</span></label>`).join('')}</div>${type==='otherChoice'||options.includes('Other')?`<div class="other-wrap" ${multi?!selected.includes('Other')?'hidden':'':state[id]!=='Other'?'hidden':''}>${otherInput(section,label)}</div>`:''}`; }
function fieldMarkup(section,field) { const [label,type,options] = field; const id=key(section,label);
  if(type==='choice'||type==='otherChoice'||type==='multiChoice') return `<div class="field-row"><span class="field-label">${label}</span><div>${chips(section,label,options,type)}</div></div>`;
  if(type==='pair') return `<div class="field-row"><span class="field-label">${label}</span><div class="inline-inputs">${options.map(side=>`<label>${side}<input data-key="${id}-${side.toLowerCase()}" data-label="${label} ${side}" value="${state[`${id}-${side.toLowerCase()}`]||''}" placeholder="e.g. 6/6"></label>`).join('')}</div></div>`;
  if(type==='visualAcuity') return visualAcuityMarkup(section,label);
  if(type==='sensoryDrawing') return sensoryDrawingMarkup(section,label);
  if(type==='text'||type==='textarea') { const input=type==='textarea'?`<textarea rows="3" data-key="${id}" data-label="${label}" placeholder="Write finding">${state[id]||''}</textarea>`:`<input data-key="${id}" data-label="${label}" value="${state[id]||''}" placeholder="Write finding">`; return `<div class="field-row"><span class="field-label">${label}</span>${input}</div>`; }
  if(type==='power') return powerMarkup(section,id);
  if(type==='visual') return visualMarkup(section,label);
}
function powerMarkup(section,id) { const view=state[`${id}-view`]||'screen'; const screening=['Shoulder abduction','Shoulder adduction','Elbow flexion','Elbow extension','Wrist flexion','Wrist extension','Finger flexion','Finger abduction','Finger extension','Hip flexion','Hip extension','Knee flexion','Knee extension','Ankle dorsiflexion','Plantarflexion']; const additional=['Neck flexion','Neck extension','APB','FDI','ADM','Hip abduction','Hip adduction','Ankle inversion','Ankle eversion']; const scores=['5','4+','4','4−','3','2','1','0']; const row=(name)=>{const rowId=`${id}-${slug(name)}`, normal=state[`${rowId}-normal`]||false; const select=(side)=>`<select data-power-score data-key="${rowId}-${side}" aria-label="${name} ${side}"><option value=""></option>${scores.map(score=>`<option ${(state[`${rowId}-${side}`]||'')===score?'selected':''}>${score}</option>`).join('')}</select>`; return `<div class="power-row" data-power-row data-name="${name}"><span>${name}</span><button type="button" class="power-normal ${normal?'selected':''}" data-power-normal="${rowId}">5/5 both</button><label>R ${select('r')}</label><label>L ${select('l')}</label></div>`;}; const pane=(name,items,description)=>{const all=items.every(item=>state[`${id}-${slug(item)}-normal`]);return `<div class="power-pane" data-pane="${name}" ${view===name?'':'hidden'}><div class="power-pane-heading"><p>${description}</p><button class="power-all" type="button" data-power-all="${name}">${all?'Clear all':'Mark all 5/5'}</button></div>${items.map(row).join('')}</div>`;}; return `<div class="power-builder"><div class="power-tabs"><button type="button" class="${view==='screen'?'active':''}" data-power-view="${id}" data-view="screen">Screening</button><button type="button" class="${view==='additional'?'active':''}" data-power-view="${id}" data-view="additional">Additional</button><button type="button" class="${view==='custom'?'active':''}" data-power-view="${id}" data-view="custom">Custom</button></div>${pane('screen',screening,'Routine proximal and distal screen')}${pane('additional',additional,'Additional focal neuromuscular testing')}<div class="power-pane" data-pane="custom" ${view==='custom'?'':'hidden'}><textarea rows="3" data-key="${id}-custom" data-label="Power" placeholder="e.g. Neck flexion 4/5; right grip 4+/5">${state[`${id}-custom`]||''}</textarea></div></div>`; }
function visualMarkup(section,label) { const id=key(section,label), selected=state[id]||[]; const cells=['LU','RU','LL','RL']; const eye=(eyeName)=>`<div class="eye-field"><strong>${eyeName} eye</strong><div class="quadrants">${cells.map(cell=>{const value=`${eyeName} ${cell}`;return `<button type="button" class="quadrant ${selected.includes(value)?'selected':''}" data-field="${id}" data-value="${value}" aria-label="${eyeName} eye ${cell}">${cell}</button>`}).join('')}</div></div>`; return `<div class="field-row visual-row"><span class="field-label">${label}</span><div><div class="visual-actions"><button type="button" class="visual-normal ${selected.includes('Normal')?'selected':''}" data-field="${id}" data-normal="true">Normal</button><button type="button" class="visual-other ${selected.includes('Other')?'selected':''}" data-field="${id}" data-other="true">Other</button></div><div class="visual-grid">${eye('Left')}${eye('Right')}</div><div class="other-wrap" ${selected.includes('Other')?'':'hidden'}>${otherInput(section,label)}</div></div></div>`; }
function visualAcuityMarkup(section,label) { const id=key(section,label), glasses=state[`${id}-glasses`]==='true'; const eye=side=>`<label>${side}<input data-key="${id}-${side.toLowerCase()}" data-label="${label} ${side}" value="${state[`${id}-${side.toLowerCase()}`]||''}" placeholder="e.g. 6/12"><small>Pinhole</small><input data-key="${id}-${side.toLowerCase()}-pinhole" data-label="${label} ${side} pinhole" value="${state[`${id}-${side.toLowerCase()}-pinhole`]||''}" placeholder="e.g. 6/6"></label>`; return `<div class="field-row visual-acuity-row"><span class="field-label">${label}</span><div><div class="visual-acuity-inputs">${eye('R')}${eye('L')}</div><button type="button" class="glasses-button ${glasses?'selected':''}" data-visual-glasses="${id}">Glasses used</button><input type="hidden" data-key="${id}-glasses" value="${glasses?'true':''}"></div></div>`; }
const SENSORY_FINDINGS=['Reduced','Absent','Altered','Hyperalgesia'];
const SENSORY_MODALITIES=['Pinprick','Temperature'];
function sensoryMapData(value) { try { const parsed=JSON.parse(value||'{}'); return parsed&&typeof parsed==='object'&&!Array.isArray(parsed)?parsed:{}; } catch { return {}; } }
function sensoryMapMarkup(section,label) { const id=key(section,label), selected=sensoryMapData(state[id]); const regions=[['face','Face',75,26,11,12],['chest','Chest / abdomen',75,57,19,24],['right-arm','Right arm',43,57,7,21],['left-arm','Left arm',107,57,7,21],['right-hand','Right hand',36,82,6,7],['left-hand','Left hand',114,82,6,7],['right-thigh','Right thigh',64,94,8,19],['left-thigh','Left thigh',86,94,8,19],['right-lower-leg','Right lower leg',64,121,7,19],['left-lower-leg','Left lower leg',86,121,7,19],['right-foot','Right foot',62,143,8,6],['left-foot','Left foot',88,143,8,6]]; const figure=view=>`<div class="body-figure"><span>${view}</span><svg viewBox="0 0 150 156" role="group" aria-label="${view} body map"><path class="body-outline" d="M75 12c-9 0-15 7-15 16 0 7 3 11 7 14l-5 12H50l-7 30h10l3-22h6l3 29-10 55h17l3-43 3 43h17L85 91l3-29h6l3 22h10l-7-30H88l-5-12c4-3 7-7 7-14 0-9-6-16-15-16Z"/><g class="body-regions">${regions.map(([region,regionLabel,x,y,w,h])=>{const finding=selected[`${view}-${region}`]||'',displayX=view==='Back'?150-x:x;return `<g tabindex="0" role="button" aria-label="${view} ${regionLabel}${finding?`, ${finding}`:''}" aria-pressed="${finding?'true':'false'}" class="sensory-region ${finding?'selected':''}" data-sensory-region="${view}-${region}" data-sensory-label="${view.toLowerCase()} ${regionLabel.toLowerCase()}" data-sensory-finding="${finding}"><rect x="${displayX-w/2}" y="${y-h/2}" width="${w}" height="${h}" rx="${Math.min(w,h)/2}"/></g>`;}).join('')}</g></svg></div>`; return `<div class="field-row sensory-map-row"><span class="field-label">${label}</span><div class="sensory-map"><p class="sensory-map-help">Choose a finding, then tap each affected region. Tap a marked region again to remove it.</p><div class="sensory-finding-choices">${SENSORY_FINDINGS.map((finding,index)=>`<button type="button" class="sensory-finding ${index===0?'active':''}" data-sensory-finding-choice="${finding}">${finding}</button>`).join('')}</div><div class="body-maps">${figure('Front')}${figure('Back')}</div><input type="hidden" data-key="${id}" data-label="${label}" value="${JSON.stringify(selected).replace(/"/g,'&quot;')}"><input class="sensory-map-detail" data-key="${id}-detail" data-label="Sensory map detail" value="${state[`${id}-detail`]||''}" placeholder="Optional distribution detail, e.g. left T10 sensory level"></div></div>`; }
function sensoryDrawingData(value) { try { const parsed=JSON.parse(value||'[]'); return Array.isArray(parsed)?parsed:[]; } catch { return []; } }
function sensoryDrawingMarkup(section,label) { const id=key(section,label), drawings=sensoryDrawingData(state[id]), view=state[`${id}-view`]||'Front'; const svg=viewName=>`<svg class="sensory-draw-canvas" data-sensory-draw data-view="${viewName}" viewBox="0 0 150 156" aria-label="${viewName} body map — draw the affected area"><path class="body-outline" d="M75 12c-9 0-15 7-15 16 0 7 3 11 7 14l-5 12H50l-7 30h10l3-22h6l3 29-10 55h17l3-43 3 43h17L85 91l3-29h6l3 22h10l-7-30H88l-5-12c4-3 7-7 7-14 0-9-6-16-15-16Z"/><g data-sensory-strokes>${drawings.filter(stroke=>stroke.view===viewName).map(stroke=>`<polyline class="sensory-stroke" points="${stroke.points.map(point=>point.join(',')).join(' ')}"/>`).join('')}</g></svg>`; return `<div class="field-row sensory-map-row"><span class="field-label">${label}</span><div class="sensory-drawing"><p class="sensory-map-help">Choose a finding, then draw or circle the affected area. The note will use an approximate anatomical description.</p><div class="sensory-finding-choices">${SENSORY_FINDINGS.map((finding,index)=>`<button type="button" class="sensory-finding ${index===0?'active':''}" data-sensory-drawing-finding="${finding}">${finding}</button>`).join('')}</div><div class="drawing-view-tabs"><button type="button" class="${view==='Front'?'active':''}" data-sensory-view="Front">Front</button><button type="button" class="${view==='Back'?'active':''}" data-sensory-view="Back">Back</button></div><div class="drawing-stage">${svg(view)}</div><div class="drawing-actions"><button type="button" data-sensory-undo>Undo last mark</button><button type="button" data-sensory-clear>Clear drawing</button></div><input type="hidden" data-key="${id}" data-label="${label}" value="${JSON.stringify(drawings).replace(/"/g,'&quot;')}"><input type="hidden" data-key="${id}-view" value="${view}"><input class="sensory-map-detail" data-key="${id}-detail" data-label="Sensory map detail" value="${state[`${id}-detail`]||''}" placeholder="Optional refinement, e.g. in an L5 distribution"></div></div>`; }
function tableMarkup(section,table,title) { return `<div class="table-wrap"><table class="exam-table"><thead><tr><th>${title}</th>${table.columns.map(c=>`<th>${c}</th>`).join('')}</tr></thead><tbody>${table.rows.map(row=>`<tr><td>${row}</td>${table.columns.map(col=>{const id=key(section,`${row}-${col}`), value=state[id]||'';return `<td><select data-key="${id}" data-label="${row} ${col}"><option value=""></option>${table.values.map(option=>`<option ${option===value?'selected':''}>${option}</option>`).join('')}</select></td>`}).join('')}</tr>`).join('')}</tbody></table></div>`; }
function sensoryDrawingMarkup(section,label) { const id=key(section,label), drawings=sensoryDrawingData(state[id]), svg=view=>`<svg class="sensory-draw-canvas" data-sensory-draw data-view="${view}" viewBox="0 0 150 156" aria-label="${view} body map — draw the affected area"><path class="body-outline" d="M75 12c-9 0-15 7-15 16 0 7 3 11 7 14l-5 12H50l-7 30h10l3-22h6l3 29-10 55h17l3-43 3 43h17L85 91l3-29h6l3 22h10l-7-30H88l-5-12c4-3 7-7 7-14 0-9-6-16-15-16Z"/><g data-sensory-strokes>${drawings.filter(stroke=>stroke.view===view).map(stroke=>`<polyline class="sensory-stroke" points="${stroke.points.map(point=>point.join(',')).join(' ')}"/>`).join('')}</g><text class="body-view-label" x="75" y="154" text-anchor="middle">${view}</text></svg>`; return `<div class="field-row sensory-map-row"><span class="field-label">${label}</span><div class="sensory-drawing"><p class="sensory-map-help">Choose the modality and finding, then draw or circle the affected area. The note uses an approximate anatomical description.</p><div class="sensory-modality-tabs">${SENSORY_MODALITIES.map((modality,index)=>`<button type="button" class="sensory-modality ${index===0?'active':''}" data-sensory-modality="${modality}">${modality}</button>`).join('')}</div><div class="sensory-finding-choices">${SENSORY_FINDINGS.map((finding,index)=>`<button type="button" class="sensory-finding ${index===0?'active':''}" data-sensory-drawing-finding="${finding}">${finding}</button>`).join('')}</div><div class="drawing-stage drawing-stage-dual">${svg('Front')}${svg('Back')}</div><div class="drawing-actions"><button type="button" data-sensory-undo>Undo last mark</button><button type="button" data-sensory-clear>Clear drawing</button></div><input type="hidden" data-key="${id}" data-label="${label}" value="${JSON.stringify(drawings).replace(/"/g,'&quot;')}"><input class="sensory-map-detail" data-key="${id}-detail" data-label="Sensory detail" value="${state[`${id}-detail`]||''}" placeholder="Optional refinement, e.g. in an L5 distribution"></div></div>`; }
sections.forEach(section=>{ const el=document.createElement('section'); el.className='exam-section'; el.id=section.id; el.innerHTML=`<div class="section-heading"><span class="section-icon">${section.icon}</span><h2>${section.title}</h2><button class="section-normal" type="button" data-section-normal="${section.id}">Select all normal</button></div>${section.groups.map(g=>`<fieldset class="sheet-group"><legend>${g.title}</legend>${g.fields?g.fields.map(f=>fieldMarkup(section,f)).join(''):tableMarkup(section,g.table,g.title)}</fieldset>`).join('')}`; root.append(el); const tab=document.createElement('button'); tab.type='button';tab.dataset.tab=section.id;tab.textContent=section.title;tab.addEventListener('click',()=>showTab(section.id));nav.append(tab); });
function renderPathway(id) { const pathway=PATHWAYS[id];if(!pathway){pathwayRoot.innerHTML='';return;}const pathwaySection={id:`pathway-${id}`};pathwayRoot.innerHTML=`<section id="${pathwaySection.id}" class="exam-section pathway-exam"><div class="section-heading"><span class="section-icon"></span><h2>${pathway.title}</h2><button class="section-normal" type="button" data-section-normal="${pathwaySection.id}">Select all normal</button></div>${pathway.groups.map(([title,fields])=>`<fieldset class="sheet-group"><legend>${title}</legend>${fields.map(field=>fieldMarkup(pathwaySection,field)).join('')}</fieldset>`).join('')}</section>`;}
function showTab(id) { active=id; document.querySelectorAll('.exam-section').forEach(el=>el.hidden=el.id!==id); document.querySelectorAll('[data-tab]').forEach(el=>el.classList.toggle('active',el.dataset.tab===id)); save(); }
function applyExamTemplate() { const allowed=TEMPLATE_SECTIONS.detailed; document.querySelectorAll('[data-tab]').forEach(button=>button.hidden=!allowed.includes(button.dataset.tab)); if(!allowed.includes(active))active=allowed[0]; if(examMode==='detailed')showTab(active); }
function showExamMode(mode) { examMode=mode; document.body.dataset.examMode=mode; document.querySelector('#exam-mode-state').value=mode; quickRoot.hidden=mode!=='quick'; pathwayRoot.hidden=mode!=='pathway'; document.querySelectorAll('[data-exam-mode]').forEach(button=>button.classList.toggle('active',button.dataset.examMode===mode)); if(mode==='detailed')applyExamTemplate(); save(); }
function save() { const saved={patient:document.querySelector('#patient').value,date:document.querySelector('#exam-date').value,active}; document.querySelectorAll('input[type=radio]:checked').forEach(el=>saved[el.name]=el.value); document.querySelectorAll('[data-multi-key]').forEach(el=>{const id=el.dataset.multiKey;saved[id]??=[];if(el.checked)saved[id].push(el.value);}); document.querySelectorAll('[data-key]').forEach(el=>saved[el.dataset.key]=el.value); document.querySelectorAll('[data-power-normal]').forEach(el=>saved[`${el.dataset.powerNormal}-normal`]=el.classList.contains('selected')); document.querySelectorAll('[data-power-view]').forEach(el=>{if(el.classList.contains('active'))saved[`${el.dataset.powerView}-view`]=el.dataset.view;}); document.querySelectorAll('.visual-row').forEach(row=>{const id=row.querySelector('[data-field]').dataset.field;saved[id]=[...row.querySelectorAll('[data-field].selected')].map(el=>el.dataset.normal?'Normal':el.dataset.other?'Other':el.dataset.value);}); Object.assign(state,saved); if(!WEBSITE_MODE)localStorage.setItem('neuro-sheet-v2',JSON.stringify(saved)); const chosen=[...document.querySelectorAll('input[type=radio]:checked, input[data-multi-key]:checked, [data-key]')].filter(el=>el.matches('input[type=radio],input[data-multi-key]')||el.value.trim()).length + document.querySelectorAll('[data-power-normal].selected, .visual-row [data-field].selected').length; document.querySelector('#progress').textContent=chosen?`${chosen} item${chosen===1?'':'s'} recorded`:'No tests selected yet'; }
function savedExams() { try { return JSON.parse(localStorage.getItem(SAVED_EXAMS_KEY) || '[]'); } catch { return []; } }
function escapeHtml(value) { const el=document.createElement('div'); el.textContent=value; return el.innerHTML; }
function renderSavedExams() { const list=document.querySelector('#saved-exams-list'), exams=savedExams(); if(!exams.length){list.innerHTML='<p class="empty-saves">No saved examinations yet.</p>';return;} list.innerHTML=exams.map(exam=>`<div class="saved-exam"><div><div class="saved-exam-title">${escapeHtml(exam.label)}</div><div class="saved-exam-meta">Exam date: ${escapeHtml(exam.date||'Not set')} · Saved ${new Date(exam.savedAt).toLocaleString()}</div></div><div class="saved-exam-actions"><button class="open-saved" type="button" data-open-exam="${exam.id}">Open</button><button class="delete-saved" type="button" data-delete-exam="${exam.id}">Delete</button></div></div>`).join(''); }
function showPage(id) { document.querySelectorAll('.app-page').forEach(page=>page.hidden=page.id!==id); document.querySelectorAll('[data-page]').forEach(button=>button.classList.toggle('active',button.dataset.page===id)); if(id==='saved-page')renderSavedExams(); window.scrollTo({top:0,behavior:'smooth'}); }
function saveExam() { save(); let snapshot=JSON.parse(localStorage.getItem('neuro-sheet-v2')||'{}'), label=snapshot.patient.trim(); if(!label) label=prompt('Enter a patient identifier to save this examination:','')?.trim(); if(!label)return; snapshot.patient=label; localStorage.setItem('neuro-sheet-v2',JSON.stringify(snapshot)); const exams=savedExams(); exams.unshift({id:crypto.randomUUID?.()||`${Date.now()}-${Math.random()}`,label,date:snapshot.date||'',savedAt:new Date().toISOString(),data:snapshot}); localStorage.setItem(SAVED_EXAMS_KEY,JSON.stringify(exams)); showPage('saved-page'); }
function openSavedExam(id) { const exam=savedExams().find(item=>item.id===id); if(!exam)return; localStorage.setItem('neuro-sheet-v2',JSON.stringify(exam.data)); location.reload(); }
function deleteSavedExam(id) { const exam=savedExams().find(item=>item.id===id); if(!exam||!confirm(`Delete the saved examination for ${exam.label}?`))return; localStorage.setItem(SAVED_EXAMS_KEY,JSON.stringify(savedExams().filter(item=>item.id!==id))); renderSavedExams(); }
function visualFieldLines(row) { const id=row.querySelector('[data-field]').dataset.field, values=state[id]||[], lines=[]; if(values.includes('Normal'))lines.push('Visual fields: normal'); else {const remaining=values.filter(value=>value!=='Other'), left=new Set(remaining.filter(value=>value.startsWith('Left ')).map(value=>value.slice(5))),right=new Set(remaining.filter(value=>value.startsWith('Right ')).map(value=>value.slice(6))), has=(eye,cells)=>cells.every(cell=>eye.has(cell)); let summary=''; if(has(left,['LU','RU','LL','RL']))summary='complete visual field loss in the left eye'; else if(has(right,['LU','RU','LL','RL']))summary='complete visual field loss in the right eye'; else if(has(left,['LU','LL'])&&has(right,['LU','LL']))summary='left homonymous hemianopia'; else if(has(left,['RU','RL'])&&has(right,['RU','RL']))summary='right homonymous hemianopia'; else if(has(left,['LU','LL'])&&has(right,['RU','RL']))summary='bitemporal hemianopia'; else if(has(left,['RU','RL'])&&has(right,['LU','LL']))summary='binasal hemianopia'; else {const quadrants=[['LU','left superior quadrantanopia'],['LL','left inferior quadrantanopia'],['RU','right superior quadrantanopia'],['RL','right inferior quadrantanopia']]; const match=quadrants.find(([cell])=>left.has(cell)&&right.has(cell)); if(match)summary=`${match[1]} (homonymous)`;} if(!summary&&remaining.length){const names={LU:'upper-left quadrant',RU:'upper-right quadrant',LL:'lower-left quadrant',RL:'lower-right quadrant'};summary=remaining.map(value=>{const [eye,quadrant]=value.split(' ');return `${eye.toLowerCase()} eye ${names[quadrant]} defect`;}).join(', ');} if(summary)lines.push(`Visual fields: ${summary}`); const other=row.querySelector('.other-wrap [data-key]')?.value.trim();if(other)lines.push(`Visual fields: ${other}`);} return lines; }
function powerFieldLines(builder) { const lines=[]; builder.querySelectorAll('[data-power-row]').forEach(row=>{const r=row.querySelector('[data-power-score][data-key$="-r"]').value,l=row.querySelector('[data-power-score][data-key$="-l"]').value;if(row.querySelector('[data-power-normal]').classList.contains('selected'))lines.push([row.dataset.name,`${row.dataset.name}: 5/5 bilaterally`]);else if(r||l)lines.push([row.dataset.name,`${row.dataset.name}: ${r?`R ${r}/5`:''}${r&&l?', ':''}${l?`L ${l}/5`:''}`]);}); lines.sort((a,b)=>POWER_ORDER.indexOf(a[0])-POWER_ORDER.indexOf(b[0])); const custom=builder.querySelector('textarea[data-key]')?.value.trim();return [...lines.map(([,line])=>line),...(custom?[`Power: ${custom}`]:[])]; }
function sensoryMapLines(map) { const data=sensoryMapData(map.querySelector('input[type=hidden][data-key]').value), groups={}; map.querySelectorAll('[data-sensory-region]').forEach(region=>{const finding=data[region.dataset.sensoryRegion];if(finding)(groups[finding]??=[]).push(region.dataset.sensoryLabel);}); const lines=Object.entries(groups).map(([finding,regions])=>`Sensory map: ${finding.toLowerCase()} sensation over ${regions.join(', ')}`); const detail=map.querySelector('.sensory-map-detail').value.trim();if(detail)lines.push(`Sensory map: ${detail}`);return lines; }
function sensoryDrawingLocation(stroke) { const average=stroke.points.reduce((total,[x,y])=>[total[0]+x,total[1]+y],[0,0]).map(total=>total/stroke.points.length),[x,y]=average, front=stroke.view==='Front', right=front?x<75:x>75, side=right?'right':'left'; if(y<22)return `${front?'anterior':'posterior'} forehead`; if(y<34)return `${side} cheek`; if(y<43)return `${side} jaw`; if(y<59&&Math.abs(x-75)<19)return `${front?'anterior chest':'upper back'}`; if(y<87&&Math.abs(x-75)<19)return `${front?'anterior abdomen':'lower back'}`; if(y<67&&Math.abs(x-75)>=19)return `${side} upper arm`; if(y<82&&Math.abs(x-75)>=19)return `${side} forearm`; if(y<91&&Math.abs(x-75)>=19)return `${side} hand`; const legCenter=right?(front?64:86):(front?86:64), outer=right?(front?x<legCenter:x>legCenter):(front?x>legCenter:x<legCenter), surface=outer?'lateral':'medial'; if(y>140)return `${side} ${surface} foot`; if(y>128)return `${side} ${surface} ankle`; if(y>108)return `${side} ${surface} lower leg`; return `${side} thigh`; }
function sensoryDrawingLines(drawing) { const strokes=sensoryDrawingData(drawing.querySelector('input[type=hidden][data-key]').value), groups={}; strokes.forEach(stroke=>{const modality=stroke.modality||'Pinprick',finding=stroke.finding.toLowerCase(),location=sensoryDrawingLocation(stroke),groupKey=`${modality}|${finding}`;(groups[groupKey]??=[]).push(location);}); const lines=Object.entries(groups).map(([key,locations])=>{const [modality,finding]=key.split('|');return `${modality}: ${finding} sensation over ${[...new Set(locations)].join(', ')}`;}); const detail=drawing.querySelector('.sensory-map-detail').value.trim();if(detail)lines.push(detail);return lines; }
function fieldRowLines(row) { const builder=row.querySelector('.power-builder');if(builder)return powerFieldLines(builder);const sensoryDrawing=row.querySelector('.sensory-drawing');if(sensoryDrawing)return sensoryDrawingLines(sensoryDrawing);const sensoryMap=row.querySelector('.sensory-map');if(sensoryMap)return sensoryMapLines(sensoryMap);if(row.classList.contains('visual-row'))return visualFieldLines(row);if(row.classList.contains('visual-acuity-row')){const value=side=>row.querySelector(`[data-key$="-${side}"]`)?.value.trim(), pinhole=side=>row.querySelector(`[data-key$="-${side}-pinhole"]`)?.value.trim(), eye=side=>{const acuity=value(side),ph=pinhole(side);return acuity?`${side.toUpperCase()} ${acuity}${ph?` (pinhole ${ph})`:''}`:'';};const eyes=['r','l'].map(eye).filter(Boolean),glasses=row.querySelector('[data-visual-glasses]')?.classList.contains('selected');return eyes.length?[`Visual acuity: ${eyes.join(', ')}${glasses?' (with glasses)':''}`]:glasses?['Visual acuity assessed with glasses']:[];} const checked=row.querySelector('input[type=radio]:checked');if(checked){const other=checked.value==='Other'?row.querySelector('.other-wrap [data-key]')?.value.trim():'';return [other?`${checked.dataset.label}: ${other}`:`${checked.dataset.label}: ${checked.value}`];} const checkedMulti=[...row.querySelectorAll('input[data-multi-key]:checked')];if(checkedMulti.length){const other=checkedMulti.some(input=>input.value==='Other')?row.querySelector('.other-wrap [data-key]')?.value.trim():'';const values=checkedMulti.filter(input=>input.value!=='Other').map(input=>input.value);if(other)values.push(other);return values.length?[`${checkedMulti[0].dataset.label}: ${values.join(', ')}`]:[];} return [...row.querySelectorAll('[data-key]:not([data-power-score])')].filter(control=>!control.closest('.other-wrap')&&!control.closest('.power-builder')).map(control=>control.value.trim()?`${control.dataset.label}: ${control.value.trim()}`:'').filter(Boolean); }
function linesFor(section) { if(examMode==='quick'){const card=document.querySelector(`[data-quick-section="${section.id}"]`);if(!card)return [];const normal=card.querySelector('[data-key$="-normal"]').value==='true',other=card.querySelector('textarea').value.trim();return other?[other]:normal?[card.dataset.normalLabel]:[];} const lines=[]; document.querySelectorAll(`#${section.id} .sheet-group`).forEach(group=>{[...group.children].forEach(child=>{if(child.classList.contains('field-row'))lines.push(...fieldRowLines(child));if(child.classList.contains('table-wrap'))child.querySelectorAll('select[data-key]').forEach(select=>{if(select.value)lines.push(`${select.dataset.label}: ${select.value}`);});});}); return [...new Set(lines)]; }
function generateBulletNote(header,dateText) { if(examMode==='pathway'){const pathway=PATHWAYS[examTemplate], groups=[...pathwayRoot.querySelectorAll('.sheet-group')].map(group=>{const lines=[...group.children].flatMap(child=>child.classList.contains('field-row')?fieldRowLines(child):[]);return lines.length?`${group.querySelector('legend').textContent.toUpperCase()}\n${lines.map(line=>`• ${line}`).join('\n')}`:'';}).filter(Boolean);return `${header}${dateText?` (${dateText})`:''}\n\n${pathway.title.toUpperCase()}\n\n${groups.length?groups.join('\n\n'):'No findings selected.'}`;} const body=sections.map(section=>{const lines=linesFor(section); return lines.length?`${section.title.toUpperCase()}\n${lines.map(line=>`• ${line}`).join('\n')}`:'';}).filter(Boolean); return `${header}${dateText?` (${dateText})`:''}\n\n${body.length?body.join('\n\n'):'No examination findings selected.'}`; }
function isNormalLine(line) { return /: (normal|no|none|negative|midline|full|equal and reactive|alert|down|2\+|−|5\/5 bilaterally)$/i.test(line); }
function marked(value,abnormal=true) { return abnormal?`**${value}**`:value; }
function sectionProse(title,lines) { if(!lines.length)return ''; const neutral=lines.filter(line=>/^Visual acuity:/.test(line)), assessed=lines.filter(line=>!neutral.includes(line)), abnormal=assessed.filter(line=>!isNormalLine(line)), detail=neutral.length?` ${neutral.join('; ')}.`:''; if(!assessed.length)return `${title}: ${neutral.join('; ')}.`; if(!abnormal.length)return `${title} was normal in the recorded domains.${detail}`; if(abnormal.length<assessed.length)return `${title} was normal apart from ${abnormal.map(line=>marked(line)).join('; ')}.${detail}`; return `${title}: ${abnormal.map(line=>marked(line)).join('; ')}.${detail}`; }
function powerProse() { const builder=document.querySelector('#motor .power-builder'); if(!builder)return ''; const tested=[]; builder.querySelectorAll('[data-power-row]').forEach(row=>{const name=row.dataset.name, normal=row.querySelector('[data-power-normal]').classList.contains('selected'), r=row.querySelector('[data-power-score][data-key$="-r"]').value, l=row.querySelector('[data-power-score][data-key$="-l"]').value; if(normal||r||l)tested.push({name,normal:normal||(r==='5'&&l==='5'),r,l});}); if(!tested.length)return ''; const upper=tested.some(item=>['Shoulder','Elbow','Wrist','Finger','APB','FDI','ADM'].some(part=>item.name.startsWith(part))), lower=tested.some(item=>['Hip','Knee','Ankle','Plantarflexion'].some(part=>item.name.startsWith(part))); const scope=upper&&lower?'Upper and lower limb power':upper?'Upper limb power':lower?'Lower limb power':'Power'; const weak=[]; tested.filter(item=>!item.normal).forEach(item=>{if(item.r&&item.r!=='5')weak.push(`right ${item.name.toLowerCase()} weakness (${item.r}/5)`); if(item.l&&item.l!=='5')weak.push(`left ${item.name.toLowerCase()} weakness (${item.l}/5)`);}); if(!weak.length)return `${scope} was normal in the tested muscle groups.`; const normalCount=tested.filter(item=>item.normal).length; return normalCount?`${scope} was normal apart from ${weak.map(item=>marked(item)).join(' and ')}.`:`${scope} showed ${weak.map(item=>marked(item)).join(' and ')}.`; }
function coordinationProse(lines) { const ataxia=lines.filter(line=>/ataxia/i.test(line)); if(!ataxia.length)return sectionProse('Coordination',lines); const sides=[...new Set(ataxia.map(line=>line.match(/:\s*([RL]) ataxia/i)?.[1]).filter(Boolean))], side=sides.length===2?'bilateral':sides[0]==='R'?'right-sided':sides[0]==='L'?'left-sided':''; const tests=[...new Set(ataxia.map(line=>line.startsWith('Finger–nose')?'finger–nose':line.startsWith('Heel–shin')?'heel–shin':'coordination'))], testText=tests.length===2?'finger–nose and heel–shin':tests.join(' and '); const extras=lines.filter(line=>!ataxia.includes(line)&&!isNormalLine(line)); return `Coordination was abnormal with ${marked(`${side?`${side} `:''}appendicular ataxia on ${testText} testing`)}.${extras.length?` ${extras.map(line=>marked(line)).join('; ')}.`:''}`; }
function proseNote(header,dateText) { const findings=[]; const mental=linesFor(sections[0]); if(mental.length)findings.push(sectionProse('Mental status',mental)); const cranial=linesFor(sections[1]); if(cranial.length)findings.push(sectionProse('Cranial nerve examination',cranial)); const motor=linesFor(sections[2]).filter(line=>!POWER_ORDER.some(name=>line.startsWith(`${name}:`))&&!line.startsWith('Power:')); const motorParts=[sectionProse('Motor examination',motor),powerProse()].filter(Boolean); if(motorParts.length)findings.push(motorParts.join(' ')); const reflexes=linesFor(sections[3]);if(reflexes.length)findings.push(sectionProse('Reflexes',reflexes)); const coordination=linesFor(sections[4]);if(coordination.length)findings.push(coordinationProse(coordination)); ['Sensation','Gait'].forEach((title,index)=>{const lines=linesFor(sections[index+5]);if(lines.length)findings.push(sectionProse(title,lines));}); return `${header}${dateText?` (${dateText})`:''}\n\n${findings.length?findings.join('\n\n'):'No examination findings selected.'}`; }
function previewHtml(markdown) { return escapeHtml(markdown).replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>').replace(/\n/g,'<br>'); }
function generateNote() { save(); const header=document.querySelector('#patient').value.trim()?`Neurological examination — ${document.querySelector('#patient').value.trim()}`:'Neurological examination'; const date=document.querySelector('#exam-date').value, dateText=date?new Date(`${date}T12:00:00`).toLocaleDateString(undefined,{day:'numeric',month:'short',year:'numeric'}):''; noteOutput.value=generateBulletNote(header,dateText); notePanel.hidden=false; notePanel.scrollIntoView({behavior:'smooth',block:'start'}); }
document.querySelector('#save-exam-button').addEventListener('click',saveExam);
document.addEventListener('click',event=>{const mode=event.target.closest('[data-exam-mode]');if(mode)showExamMode(mode.dataset.examMode);});
