quickRoot.addEventListener('click',event=>{const allNormal=event.target.closest('[data-quick-normal-all]');if(allNormal){quickRoot.querySelectorAll('[data-quick-section]').forEach(card=>{card.querySelector('[data-quick-normal]').classList.add('selected');card.querySelector('[data-key$="-normal"]').value='true';card.querySelector('textarea').value='';});save();return;}const normal=event.target.closest('[data-quick-normal]');if(!normal)return;event.preventDefault();normal.classList.toggle('selected');normal.parentElement.querySelector('[data-key$="-normal"]').value=normal.classList.contains('selected')?'true':'';save();});
quickRoot.addEventListener('input',event=>{const other=event.target.closest('textarea[data-key$="-other"]');if(!other)return;const card=other.closest('[data-quick-section]'),normal=card.querySelector('[data-quick-normal]');if(other.value.trim()){normal.classList.remove('selected');card.querySelector('[data-key$="-normal"]').value='';}save();});
function updateSensoryRegion(region) { const map=region.closest('.sensory-map'), hidden=map.querySelector('input[type=hidden][data-key]'), data=sensoryMapData(hidden.value), active=map.querySelector('.sensory-finding.active').dataset.sensoryFindingChoice, key=region.dataset.sensoryRegion; if(data[key]===active)delete data[key];else data[key]=active; hidden.value=JSON.stringify(data); const finding=data[key]||'';region.classList.toggle('selected',Boolean(finding));region.dataset.sensoryFinding=finding;region.setAttribute('aria-pressed',finding?'true':'false');region.setAttribute('aria-label',`${region.dataset.sensoryLabel}${finding?`, ${finding}`:''}`);save(); }
document.addEventListener('click',event=>{const choice=event.target.closest('[data-sensory-finding-choice]');if(choice){const map=choice.closest('.sensory-map');map.querySelectorAll('[data-sensory-finding-choice]').forEach(button=>button.classList.toggle('active',button===choice));return;}const region=event.target.closest('[data-sensory-region]');if(region)updateSensoryRegion(region);});
