let activeSensoryStroke=null;
function sensoryPoint(event,canvas) { const point=canvas.createSVGPoint();point.x=event.clientX;point.y=event.clientY;const transformed=point.matrixTransform(canvas.getScreenCTM().inverse());return [Math.max(0,Math.min(150,Math.round(transformed.x*10)/10)),Math.max(0,Math.min(156,Math.round(transformed.y*10)/10))]; }
function saveSensoryDrawing(drawing) { const hidden=drawing.querySelector('input[type=hidden][data-key]:not([data-key$="-view"])');hidden.value=JSON.stringify(sensoryDrawingData(hidden.value));save(); }
function strokeSvg(stroke) { return `<polyline class="sensory-stroke" points="${stroke.points.map(point=>point.join(',')).join(' ')}"/>`; }
document.addEventListener('pointerdown',event=>{const canvas=event.target.closest('[data-sensory-draw]');if(!canvas)return;const drawing=canvas.closest('.sensory-drawing'),finding=drawing.querySelector('[data-sensory-drawing-finding].active')?.dataset.sensoryDrawingFinding,modality=drawing.querySelector('[data-sensory-modality].active')?.dataset.sensoryModality;if(!finding||!modality)return;event.preventDefault();const stroke={view:canvas.dataset.view,modality,finding,points:[sensoryPoint(event,canvas)]};activeSensoryStroke={canvas,drawing,stroke};const mark=document.createElementNS('http://www.w3.org/2000/svg','polyline');mark.classList.add('sensory-stroke');mark.setAttribute('points',stroke.points[0].join(','));canvas.querySelector('[data-sensory-strokes]').append(mark);activeSensoryStroke.mark=mark;canvas.setPointerCapture?.(event.pointerId);});
document.addEventListener('pointermove',event=>{if(!activeSensoryStroke)return;const {canvas,stroke,mark}=activeSensoryStroke;stroke.points.push(sensoryPoint(event,canvas));mark.setAttribute('points',stroke.points.map(point=>point.join(',')).join(' '));});
document.addEventListener('pointerup',event=>{if(!activeSensoryStroke)return;const {drawing,stroke}=activeSensoryStroke;activeSensoryStroke=null;if(stroke.points.length===1)stroke.points.push([stroke.points[0][0]+.4,stroke.points[0][1]+.4]);const hidden=drawing.querySelector('input[type=hidden][data-key]:not([data-key$="-view"])'),strokes=sensoryDrawingData(hidden.value);strokes.push(stroke);hidden.value=JSON.stringify(strokes);save();});
document.addEventListener('click',event=>{const modality=event.target.closest('[data-sensory-modality]');if(modality){const drawing=modality.closest('.sensory-drawing');drawing.querySelectorAll('[data-sensory-modality]').forEach(button=>button.classList.toggle('active',button===modality));return;}const finding=event.target.closest('[data-sensory-drawing-finding]');if(finding){const drawing=finding.closest('.sensory-drawing');drawing.querySelectorAll('[data-sensory-drawing-finding]').forEach(button=>button.classList.toggle('active',button===finding));return;}const drawingAction=event.target.closest('[data-sensory-undo],[data-sensory-clear]');if(drawingAction){const drawing=drawingAction.closest('.sensory-drawing'),hidden=drawing.querySelector('input[type=hidden][data-key]');let strokes=sensoryDrawingData(hidden.value);strokes=drawingAction.hasAttribute('data-sensory-clear')?[]:strokes.slice(0,-1);hidden.value=JSON.stringify(strokes);drawing.querySelectorAll('[data-sensory-draw]').forEach(canvas=>{canvas.querySelector('[data-sensory-strokes]').innerHTML=strokes.filter(stroke=>stroke.view===canvas.dataset.view).map(strokeSvg).join('');});save();}});
document.querySelector('.app-nav').addEventListener('click',event=>{const button=event.target.closest('[data-page]');if(button)showPage(button.dataset.page);});
document.querySelector('#saved-exams-list').addEventListener('click',event=>{const open=event.target.closest('[data-open-exam]'),remove=event.target.closest('[data-delete-exam]');if(open)openSavedExam(open.dataset.openExam);if(remove)deleteSavedExam(remove.dataset.deleteExam);});
document.addEventListener('input',save); document.addEventListener('change',event=>{const radio=event.target.closest('input[type=radio]');if(radio){const wrap=radio.closest('.field-row').querySelector('.other-wrap');if(wrap)wrap.hidden=radio.value!=='Other';}const multi=event.target.closest('input[data-multi-key]');if(multi){const wrap=multi.closest('.field-row').querySelector('.other-wrap');if(wrap)wrap.hidden=!multi.closest('.field-row').querySelector('input[data-multi-key][value="Other"]:checked');}const score=event.target.closest('[data-power-score]');if(score&&score.value){score.closest('[data-power-row]').querySelector('[data-power-normal]').classList.remove('selected');}save();});
document.addEventListener('pointerdown',event=>{const chip=event.target.closest('.choice-chip');if(chip){const radio=chip.querySelector('input');radio.dataset.wasChecked=radio.checked?'true':'false';}});
document.addEventListener('click',event=>{const glasses=event.target.closest('[data-visual-glasses]');if(!glasses)return;glasses.classList.toggle('selected');glasses.parentElement.querySelector('[data-key$="-glasses"]').value=glasses.classList.contains('selected')?'true':'';save();});
document.addEventListener('click',event=>{const chip=event.target.closest('.choice-chip'),radio=chip?.querySelector('input[type=radio]');if(radio&&radio.dataset.wasChecked==='true'){event.preventDefault();radio.checked=false;const wrap=radio.closest('.field-row').querySelector('.other-wrap');if(wrap)wrap.hidden=true;radio.dataset.wasChecked='false';save();return;}const selectNormal=event.target.closest('[data-section-normal]');if(selectNormal){const section=document.querySelector(`#${selectNormal.dataset.sectionNormal}`);section.querySelectorAll('.choices').forEach(choices=>{const radio=choices.querySelector('input[type=radio]');if(radio)radio.checked=true;const checks=[...choices.querySelectorAll('input[data-multi-key]')];if(checks.length)checks.forEach(check=>check.checked=check.value==='Normal');});section.querySelectorAll('.other-wrap').forEach(wrap=>wrap.hidden=true);section.querySelectorAll('.visual-row').forEach(row=>{row.querySelectorAll('.quadrant,.visual-other').forEach(el=>el.classList.remove('selected'));row.querySelector('.visual-normal').classList.add('selected');});section.querySelectorAll('.exam-table select').forEach(select=>select.value='2+');section.querySelectorAll('[data-power-normal]').forEach(normal=>{normal.classList.add('selected');normal.closest('[data-power-row]').querySelectorAll('[data-power-score]').forEach(score=>score.value='');});save();return;}const q=event.target.closest('.quadrant');if(q){const row=q.closest('.visual-row'), normal=row.querySelector('.visual-normal');normal.classList.remove('selected');q.classList.toggle('selected');save();return;} const action=event.target.closest('.visual-normal,.visual-other');if(action){const row=action.closest('.visual-row'); if(action.classList.contains('visual-normal')){row.querySelectorAll('.quadrant,.visual-other').forEach(el=>el.classList.remove('selected'));action.classList.toggle('selected');}else{action.classList.toggle('selected');row.querySelector('.other-wrap').hidden=!action.classList.contains('selected');}save();return;}const view=event.target.closest('[data-power-view]');if(view){const builder=view.closest('.power-builder');builder.querySelectorAll('[data-power-view]').forEach(el=>el.classList.toggle('active',el===view));builder.querySelectorAll('[data-pane]').forEach(el=>el.hidden=el.dataset.pane!==view.dataset.view);save();return;}const all=event.target.closest('[data-power-all]');if(all){const pane=all.closest('.power-pane'), rows=[...pane.querySelectorAll('[data-power-normal]')], activate=!rows.every(row=>row.classList.contains('selected'));rows.forEach(row=>{row.classList.toggle('selected',activate);if(activate)row.closest('[data-power-row]').querySelectorAll('[data-power-score]').forEach(el=>el.value='');});all.textContent=activate?'Clear all':'Mark all 5/5';save();return;}const normal=event.target.closest('[data-power-normal]');if(normal){normal.classList.toggle('selected');const row=normal.closest('[data-power-row]');if(normal.classList.contains('selected'))row.querySelectorAll('[data-power-score]').forEach(el=>el.value='');save();}});
document.querySelector('#generate-button').addEventListener('click',generateNote); document.querySelector('#clear-button').addEventListener('click',()=>{if(confirm('Clear the examination sheet?')){localStorage.removeItem('neuro-sheet-v2');location.reload();}}); document.querySelector('#copy-button').addEventListener('click',async()=>{await navigator.clipboard.writeText(noteOutput.value);const b=document.querySelector('#copy-button');b.textContent='Copied';setTimeout(()=>b.textContent='Copy note',1300);}); if('serviceWorker'in navigator)navigator.serviceWorker.register('service-worker.js');if(PATHWAYS[examTemplate]){renderPathway(examTemplate);showExamMode('pathway');}else{showExamMode(examTemplate==='detailed'?'detailed':'quick');showTab(active);}
